-- Adds deep-dive content to the 64 diagnosis types: longer-form analysis text,
-- "type moments" bullets, and a compatible-type pairing for the result page.
alter table diagnosis_types
  add column personality_analysis text,
  add column ability_analysis text,
  add column growth_advice text,
  add column career_path text,
  add column type_moments text[] not null default '{}',
  add column compatible_type_id uuid references diagnosis_types(id),
  add column compatible_reason text;

-- Backfill: deep-dive content for all 64 types, generated by
-- scripts/generate-type-details-sql.ts from scripts/content/type-details/*.json.
-- Matches by type_code; no-op on a fresh install where diagnosis_types is still
-- empty at this point (seed.sql runs after migrations).
update diagnosis_types set personality_analysis = '相手の些細な変化を察知することに強い喜びを感じるタイプ。目立つことより、場の空気や体験全体を滑らかにすることに価値を置き、自分の手柄よりも「相手が心地よかったかどうか」を判断基準にする。感覚的な間合いのつかみ方に長け、マニュアル以上の気配りを自然に行える。', ability_analysis = 'ホスピタリティと技術・品質への意識がともに高く、直感的な判断で動くため、決まった型よりもその場の空気に応じた対応を得意とする。専門性を深める方向に能力が伸びやすいタイプ。', growth_advice = '気配りが「察してもらって当然」の空気を生み、感謝や評価を言葉にしにくい環境だと燃え尽きやすい。自分の仕事を可視化し、周囲に伝える習慣を持つと長く活躍できる。', career_path = '高級店やホテルでのシニアサービス職から、後進を育てる副支配人やサービス責任者へ。技術を極めるなら、独立系の名店で専門職としてキャリアを深める道も向いている。', type_moments = '{"常連さんの好みを一言も聞かずに覚えている","『いつも通り』と言われるのが一番の褒め言葉","自分が動いた分だけ、店の空気が静かに良くなるのが快感"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T05'), compatible_reason = '同じ上質接客の感覚を持ちながら、T05は現場を統率する側。プレイヤーとしての基準をチームに広げてくれる相棒になる。' where type_code = 'T01';
update diagnosis_types set personality_analysis = '感覚と経験だけに頼らず、「なぜうまくいったのか」を言語化し、誰でも再現できる形にすることに価値を感じるタイプ。感情に流されず、事実に基づいて冷静に状況を捉える。', ability_analysis = 'おもてなしの感度と分析力を併せ持ち、データに基づいて改善を積み重ねる。専門性重視で、決まった領域を深く掘り下げる働き方が向く。', growth_advice = '数字や仕組みに寄りすぎると、現場の温度感や個々のお客様の事情を見落とすことがある。分析結果を現場に伝えるときは、数字だけでなく『なぜそうなるか』の物語も添えると浸透しやすい。', career_path = 'CX改善やサービス品質管理の専門職として力を発揮しやすい。将来的には研修企画や品質責任者として、組織全体の接客レベルを底上げする役割へ。', type_moments = '{"クレームが来ると『なぜ』が気になって仕方ない","接客マニュアルの行間を自分なりに解釈して補足したくなる","『前回よりこの数字が良くなった』に地味にガッツポーズ"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T06'), compatible_reason = 'T06は同じ改善志向をチーム統括の立場で実践する存在。分析の視点をより大きな規模で活かすヒントをくれる。' where type_code = 'T02';
update diagnosis_types set personality_analysis = '『普通』に飽き足らず、既存の接客の枠を超えた体験を作ることに情熱を燃やすタイプ。発想力と行動力があり、思いついたらまず試してみる直感型。', ability_analysis = 'ホスピタリティと創造性がともに高く、挑戦志向と直感的判断が組み合わさっている。新しい打ち手を次々と生み出す推進力がある。', growth_advice = '演出が強すぎて好みが分かれたり、属人的になって標準化が弱くなることがある。仕組み化が得意な人と組むことで、アイデアを持続可能な形に落とし込める。', career_path = '体験企画やイベント接客、SNS連動企画など、新しい顧客体験をゼロから作る仕事に向く。実績を積めば新店の立ち上げやCX企画のリーダーへ。', type_moments = '{"接客に『ちょっとしたサプライズ』を仕込まずにいられない","『それ、うちでもやってみよう』が口癖","型通りの対応より、その場でのアドリブに燃える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T07'), compatible_reason = '同じ挑戦志向を持つT07は、新しい環境そのものを開拓する側。アイデアを実践する舞台を一緒に広げていける。' where type_code = 'T03';
update diagnosis_types set personality_analysis = '一つひとつの接客だけでなく、来店前から退店後までの体験全体を設計することに関心を持つ戦略家。感覚ではなくデータと論理で顧客体験を組み立てる。', ability_analysis = '顧客視点とブランド視点、分析力を兼ね備え、挑戦的な新しい仕組みをデータで裏付けながら作る。専門性の高い戦略職に向く。', growth_advice = '設計が緻密になりすぎて現場の負荷を見落とすことがある。実際に現場で運用する人の声を早い段階で取り入れると、絵に描いた戦略で終わらない。', career_path = 'CX責任者やブランド企画、CRMなど顧客体験設計の専門職からキャリアを積み、事業企画やブランド全体の顧客戦略を担う立場へ。', type_moments = '{"来店から退店までの導線を無意識に頭の中でシミュレーションしている","『なぜお客様が満足したか』を数字で説明したくなる","良い接客エピソードを聞くと、すぐ仕組み化できないか考える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T08'), compatible_reason = 'T08は同じ視座をより大きな経営スケールで体現する存在。CX戦略を会社全体の文化にまで広げる際の心強い理解者になる。' where type_code = 'T04';
update diagnosis_types set personality_analysis = '一人のお客様への丁寧な対応と、店全体を見渡す視野を同時に持つ現場リーダー。自らが接客の模範を示しながら、チームを引っ張るタイプ。', ability_analysis = '統率力と顧客対応力が高く、直感的な判断でその場の状況に応じて動く。まとめる立場としての適性が強い。', growth_advice = '責任感の強さから一人で抱え込みやすく、部下にも自分と同じ高い基準を求めすぎる傾向がある。任せることと基準を伝えることを分けて考えると、チームがより育つ。', career_path = '支配人やサービスマネージャーとして現場を率いる立場から、複数店舗を見る統括責任者や、独立して自分の店を持つ道も見えてくる。', type_moments = '{"店内のどこにいても、全テーブルの空気が同時に見えている","新人の些細なミスにいち早く気づいて自然にフォローする","『この人がいると安心』と言われるのが何より嬉しい"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T01'), compatible_reason = 'T01は同じ上質な接客感覚を持つスペシャリスト。現場の模範として並び立ち、互いの基準の高さを支え合える関係になる。' where type_code = 'T05';
update diagnosis_types set personality_analysis = '一店舗の成功体験を、仕組みとして複数店舗に広げることに使命感を持つタイプ。感覚に頼らず、基準・教育・監査という形で品質を再現しようとする。', ability_analysis = '統率力とデータに基づく標準化力を兼ね備え、複数店舗管理に強みがある。組織全体のレベルを底上げする役割に向く。', growth_advice = 'ルールや基準を整備しすぎると、現場との距離が開いたり、息苦しさを生むことがある。数値や規則だけでなく、現場に足を運んで温度感を確かめる時間を意識的に作りたい。', career_path = 'サービス統括や教育責任者、SVとして複数店舗の品質を管理する立場から、ホテルグループや高級チェーンの統括責任者へ。', type_moments = '{"どの店舗でも同じクオリティで出せているか、つい確認したくなる","『なぜこのやり方なのか』を説明できないルールが気になる","新人研修のマニュアルを見ると、つい手直ししたくなる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T02'), compatible_reason = 'T02の分析力は、統括する店舗の課題発見に直結する。現場データを一緒に読み解ける頼れるパートナーになる。' where type_code = 'T06';
update diagnosis_types set personality_analysis = '未知の環境でも『人を喜ばせる方法』を自分の力で見つけ出せるタイプ。前例のない状況に対する適応力と、現場に飛び込む行動力を兼ね備える。', ability_analysis = '共感力と挑戦心が高く、直感を頼りに新しい環境でリーダーシップを発揮する。ゼロからのスタートに強い。', growth_advice = '勢いで動く分、準備不足になったり、その場限りの対応で終わって再現性が弱くなることがある。うまくいったやり方は後から振り返って言語化しておくと、次の挑戦に活かせる。', career_path = '新店の立ち上げメンバーや海外店、イベントなど『初めての場所』で力を発揮する。経験を積めば、新規開拓を任されるサービス責任者へ。', type_moments = '{"知らない土地の店でも、すぐにお客様との距離を縮められる","『前例がない』と聞くとむしろやる気が出る","初日で常連さんのように馴染んでしまう"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T03'), compatible_reason = 'T03の発想力とT07の行動力は好相性。アイデアを出す人と、それを新しい現場で実現する人としてタッグを組める。' where type_code = 'T07';
update diagnosis_types set personality_analysis = '顧客・従業員・ブランドを一つの物語として捉え、ホスピタリティを会社全体の競争力に変えようとする経営者気質。長期的な視点で文化を作ることに情熱を注ぐ。', ability_analysis = '経営視点と長期設計力を持ち、データに基づいて大きな意思決定を行う。組織全体を動かすスケールの大きな役割に向く。', growth_advice = '理想やビジョンが大きくなりすぎて、現場の細かい実情との間にギャップが生まれやすい。定期的に現場の一次情報に触れる仕組みを自分に課すと、理想と現実の橋渡しができる。', career_path = 'ブランドCEOや事業責任者として、複数ブランド・グループ全体のホスピタリティ戦略を統括する立場へ。将来的な経営者・創業者としての適性も高い。', type_moments = '{"接客の一場面を見ただけで、会社全体の文化の話に発展させてしまう","『このホスピタリティを仕組み化したら会社の強みになる』とすぐ考える","現場の小さな成功例を聞くと、全社展開したくなる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T04'), compatible_reason = 'T04が設計するCX戦略は、T08が描く経営ビジョンの実行部隊として機能する。理想と実務をつなぐ最良のパートナー。' where type_code = 'T08';
update diagnosis_types set personality_analysis = '肩書きより、お客様一人ひとりとの関係そのものを大切にするタイプ。名前や役職を覚えられることより、『あの人が来た』と自分が気づけることに喜びを感じる。飾らない親しみやすさが自然な魅力になる。', ability_analysis = 'ホスピタリティと親近感の作り方に長け、直感的にお客様との距離を縮める。専門性重視で、接客の現場そのものを極めていくタイプ。', growth_advice = '常連さんを優先しすぎたり、距離が近くなりすぎることがある。誰にでも公平な心地よさを届ける意識を持つと、より多くのファンを作れる。', career_path = 'ホールやカフェスタッフとして経験を積み、ホールリーダーへ。人との関係づくりを武器に、地域に根ざした店舗の顔として活躍できる。', type_moments = '{"常連さんの顔を見た瞬間、注文より先に近況を聞いてしまう","『今日は元気ないね』にすぐ気づく","お客様に名前で呼ばれると、その日一日のモチベーションが上がる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T13'), compatible_reason = 'T13は同じ親しみやすさをチーム全体に広げる店長タイプ。現場で築いた信頼関係を、店全体の空気づくりに活かしてくれる。' where type_code = 'T09';
update diagnosis_types set personality_analysis = '誰が担当しても同じ心地よさを届けられる状態を目指すタイプ。忙しさの中でも一定の品質を保つことに誇りを持ち、感覚ではなく型として接客を捉える。', ability_analysis = '効率と接客基準を両立させる力があり、データに基づいて安定運営を実現する。専門性の高いオペレーション職に向く。', growth_advice = '型を大切にするあまり、個別のお客様への柔軟な対応が弱くなることがある。基本の型を守りつつ、状況に応じたひと工夫を加える余白を持ちたい。', career_path = '接客トレーナーやオペレーション担当として経験を積み、複数店舗の接客品質を管理する時間帯責任者やトレーナーへ。', type_moments = '{"新人に接客の『型』を教えるのが得意で楽しい","オペレーションのムダを見つけると直したくなる","忙しい時間帯ほど、逆に淡々と力を発揮できる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T14'), compatible_reason = 'T14が生み出す高回転の現場を、オペレーションの型で支えられる関係。忙しさを混乱ではなく仕組みに変える名コンビ。' where type_code = 'T10';
update diagnosis_types set personality_analysis = '店を単なる飲食の場ではなく、人が集まる『居場所』にしたいと考えるタイプ。地域の人々との関係を育てることに情熱を注ぎ、自然と発信力も発揮する。', ability_analysis = '人脈づくりと親しみやすさに強みがあり、直感的に地域とのつながりを広げる。挑戦志向もあり、新しい関係づくりに前向き。', growth_advice = '内輪の空気が強くなりすぎたり、採算管理が甘くなることがある。誰でも入りやすい開かれた雰囲気と、事業としての数字管理のバランスを意識したい。', career_path = '地域店スタッフやコミュニティ運営から、店長候補やコミュニティ担当として、店を地域の拠点に育てる役割へ。', type_moments = '{"常連さん同士を自然に紹介してしまう","地域のイベントがあると、つい店を絡めたくなる","『この街のこの店』と言われることに誇りを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T15'), compatible_reason = 'T15は同じコミュニティ志向を自分の店として体現する存在。地域との関係づくりのノウハウを、独立という形で一緒に育てられる。' where type_code = 'T11';
update diagnosis_types set personality_analysis = 'お客様の『また来たい』という気持ちを、感覚ではなく数字で捉え、増やしていくことに面白さを感じるタイプ。現場の反応とデータの両方を大切にする。', ability_analysis = '分析力と顧客理解を兼ね備え、データに基づいて販促や集客の打ち手を考える。挑戦的な新しい施策にも積極的。', growth_advice = '短期的な施策に偏ったり、現場のオペレーション負荷を増やしてしまうことがある。施策を打つ前に、現場が無理なく回せるかを確認する視点を持ちたい。', career_path = '店舗マーケティングやCRM、販促担当として経験を積み、複数店舗の販促責任者やマーケティング担当へ。', type_moments = '{"リピート率の数字が上がると、地味に一番テンションが上がる","SNSの反応を見て、次の施策のヒントを探してしまう","『なぜこのメニューが売れているか』の理由が気になる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T16'), compatible_reason = 'T16が描く業態設計を、データと販促の力で後押しできる関係。戦略と実行の両輪として機能する。' where type_code = 'T12';
update diagnosis_types set personality_analysis = 'スタッフにもお客様にも『会いに来たくなる』と思わせる人柄を持つタイプ。親しみやすさと調整力で、人が自然と定着する空気をつくる。', ability_analysis = '信頼構築と育成力に強みがあり、直感的にチームの状態を把握する。まとめる立場としての適性が高い。', growth_advice = '厳しい判断を避けたり、人に頼られすぎて抱え込むことがある。時には嫌われることを恐れず伝える勇気を持つと、店全体がより健全に育つ。', career_path = '店長やカフェマネージャー、居酒屋店長として現場を率い、経験を積めばエリア店長候補として複数店舗を見る立場へ。', type_moments = '{"辞めたスタッフが『また働きたい』と戻ってくる","お客様よりスタッフの顔色にまず気づく","誰かの相談事が、いつの間にか自分に集まってくる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T09'), compatible_reason = 'T09の現場での親しみやすさは、T13が目指す店づくりそのもの。信頼できるプレイヤーとして店の顔を任せられる。' where type_code = 'T13';
update diagnosis_types set personality_analysis = '混雑や忙しさをむしろエネルギーに変えられるタイプ。ピークタイムの現場で人・席・商品を的確に動かし、活気と効率を両立させることに手応えを感じる。', ability_analysis = '即断力と配置力に優れ、データに基づいて現場を統率する。忙しい環境ほど本領を発揮するリーダー適性がある。', growth_advice = '指示が強くなりすぎたり、目の前の対応に追われて長期的な育成が後回しになることがある。落ち着いた場面でこそ、じっくり人を育てる時間を意識的に取りたい。', career_path = '店長や大型店の責任者として腕を発揮し、複数店舗を統括するSV候補として、繁盛店を作る力を組織全体に広げていく。', type_moments = '{"満席になるほど頭が冴えてくる","『何番テーブルが空くか』が常に頭の中で動いている","ピークを乗り切った後の一体感が何より好き"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T10'), compatible_reason = 'T10が作る安定したオペレーションの型は、T14の瞬発力を最大限活かす土台になる。忙しさを乗りこなす最強タッグ。' where type_code = 'T14';
update diagnosis_types set personality_analysis = '自分の好きなものや大切にしたい価値観を軸に、人が集まる場所を自分の手でつくりたいと考えるタイプ。独立心と発信力を併せ持つ。', ability_analysis = 'コミュニティづくりと独立志向に強みがあり、直感を頼りに新しい場を切り拓く。挑戦志向の高いオーナー気質。', growth_advice = '内輪の空気が強くなりすぎたり、事業として規模を広げにくくなることがある。濃いファンとの関係を大切にしつつ、新しいお客様を迎え入れる開かれた設計も意識したい。', career_path = '独立店主やコミュニティカフェのオーナーとして、自分の店を持つキャリアが向く。ブランドの発起人として、共感する仲間を増やしていく道も。', type_moments = '{"『こんな店があったらいいな』を実際に形にしてしまう","お客様がいつの間にかスタッフのように手伝ってくれる","SNSでの発信が、そのままお客様との会話のきっかけになる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T11'), compatible_reason = 'T11が持つ地域との関係づくりの力は、コミュニティを軸にした店づくりに欠かせない。二人三脚で場を育てられる。' where type_code = 'T15';
update diagnosis_types set personality_analysis = '親しみやすさという感覚的な価値を、誰もが日常的に選びたくなる『強い業態』として設計することに関心を持つタイプ。事業としてのスケールを見据えている。', ability_analysis = '業態設計と収益力に優れ、データに基づいて挑戦的な新しい仕組みを作る。事業を広げるリーダーとしての適性が高い。', growth_advice = '効率を優先しすぎて、店の個性や温かみが薄れることがある。多店舗展開のスピードと、一店舗ごとの体験の質のバランスを意識したい。', career_path = '業態開発や事業責任者、FC本部として経験を積み、大衆業態やチェーンのブランド統括として事業全体を率いる立場へ。', type_moments = '{"繁盛している店を見ると、つい仕組みを分析してしまう","『これは他の街でもいけるかも』とすぐ横展開を考える","価格と満足度のバランスが取れた瞬間に興奮する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T12'), compatible_reason = 'T12のマーケティング視点は、業態を広げる際の集客・販促の実行力になる。設計と実行が噛み合う理想的な組み合わせ。' where type_code = 'T16';
update diagnosis_types set personality_analysis = '『売る』のではなく『理解して選んでもらう』ことにこだわるタイプ。専門知識を武器に、お客様がまだ気づいていない価値を丁寧に伝える。信頼を積み重ねることに時間をかけられる。', ability_analysis = '提案力と専門知識を兼ね備え、直感的にお客様の好みや状況を読み取る。高価格帯の商品を扱う専門職としての適性が高い。', growth_advice = '説明が多くなりすぎたり、数字目標を意識しすぎて接客が硬くなることがある。伝えたい情報の量より、お客様が心地よく感じる間合いを優先したい。', career_path = 'ソムリエや高級販売、予約担当としての専門性を磨き、シニアサービスやセールス担当として店の顔になっていく。', type_moments = '{"お客様の一言から好みを察して、ぴったりの一本を選び当てる","説明したいことが多すぎて、時間を忘れる","『あなたに勧められたから』と言われるのが最高の喜び"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T21'), compatible_reason = 'T21は同じ高級店の基準を、現場統率という形で守る存在。専門知識を発揮する舞台を整えてくれる心強い上司役。' where type_code = 'T17';
update diagnosis_types set personality_analysis = '上質さと利益、どちらも諦めずに両立させることに使命感を持つタイプ。感覚的な高級感を、客単価や稼働率といった具体的な数字で裏付けて捉える。', ability_analysis = '収益分析と価格設計に強みがあり、データに基づいて計画的に判断する。専門性の高い管理職に向く。', growth_advice = '数字を追いすぎて現場感を失ったり、ブランド価値を数字だけで語ってしまうことがある。数字の背景にある『なぜお客様がその体験に価値を感じるか』を忘れずにいたい。', career_path = '収益管理やレベニューマネジメントの専門職として力を発揮し、ホテルや高級店の収益責任者、管理責任者へ。', type_moments = '{"予約の埋まり方を見ると、つい稼働率を計算してしまう","『高いのに理由がある』を数字で説明できると気持ちいい","原価と満足度のギリギリのバランスを見つけるのが好き"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T22'), compatible_reason = 'T22は同じ収益意識をより大きな組織運営で実践する存在。分析結果を実際の経営判断に落とし込むパートナーになる。' where type_code = 'T18';
update diagnosis_types set personality_analysis = '『憧れられる店には理由がある』という信念を持ち、料理・空間・物語を一つのブランドとして編み上げるタイプ。美意識と発信力を武器にする。', ability_analysis = 'ブランド設計力と美意識に優れ、直感を頼りに新しい世界観を生み出す。挑戦志向が高く、常に次の一手を考えている。', growth_advice = '外見や世界観づくりを優先しすぎて、現場の実情との間に乖離が生まれることがある。ブランドを支える現場の声を定期的に聞く姿勢を持ちたい。', career_path = 'ブランド企画やPR、クリエイティブ職として経験を積み、高級店やホテルのブランドマネージャーへ。', type_moments = '{"店の内装や器を見ると、その裏にあるストーリーを考えてしまう","『なぜこの店が選ばれるのか』を言語化したくなる","写真映えより、体験として語れる瞬間を作りたい"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T23'), compatible_reason = 'T23は同じ美意識を自分のブランドとして体現する存在。世界観づくりのアイデアを、実際の店として一緒に形にできる。' where type_code = 'T19';
update diagnosis_types set personality_analysis = '一店舗の名声を、一過性で終わらせず持続する事業として育てたいと考える戦略家。ブランド資産や市場を俯瞰する長期的な視点を持つ。', ability_analysis = '戦略設計と市場分析に強みがあり、データに基づいて挑戦的な成長戦略を描く。専門性の高い戦略職に向く。', growth_advice = '理論が先行し、現場への実装が遅れることがある。戦略を小さく試しながら磨いていく、実験的な進め方を意識したい。', career_path = '経営企画やブランド戦略、投資企画として経験を積み、高級グループやホテルの戦略責任者、経営企画へ。', type_moments = '{"話題の高級店を見ると、その成長戦略を分析したくなる","『このブランドは5年後どうなっているか』を考えてしまう","市場データと現場の感覚をすり合わせるのが得意"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T24'), compatible_reason = 'T24が描く経営ビジョンを、戦略として具体化する役割を担える。理想を実現可能な計画に変える名パートナー。' where type_code = 'T20';
update diagnosis_types set personality_analysis = '店の世界観やブランドの基準を、人と現場の両面から守り抜く責任感の強いタイプ。顧客対応と組織運営、どちらも自分の役割だと捉える。', ability_analysis = 'ブランド理解と統率力に優れ、直感的な判断で現場を動かす。まとめる立場としての適性が高い。', growth_advice = '基準が厳しくなりすぎたり、現場の負担を増やしてしまうことがある。基準を守ることと、スタッフが無理なく働けることのバランスを意識したい。', career_path = '支配人やGMとして高級レストランやホテルの現場を率い、ブランド全体の基準を体現する存在へ成長していく。', type_moments = '{"店の細部の乱れに誰よりも早く気づく","お客様の期待値を上回る瞬間に一番のやりがいを感じる","『このブランドらしさ』を言葉にせずとも体現できる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T17'), compatible_reason = 'T17の専門知識と提案力は、支配人として守りたいブランド体験の核になる。現場の最前線を安心して任せられる存在。' where type_code = 'T21';
update diagnosis_types set personality_analysis = 'ブランドの輝きを、感覚だけでなく強い運営の仕組みに変えたいと考えるタイプ。品質を守りながら、組織・数値・出店計画までを管理する実行力を持つ。', ability_analysis = '事業運営と組織統括、品質管理に強みがあり、データに基づいて多店舗を管理する。まとめる立場としての適性が高い。', growth_advice = '管理項目が増えすぎたり、現場との距離が開くことがある。数字だけでなく、現場に足を運んで空気を感じる時間を大切にしたい。', career_path = 'COOや事業部長、統括として経験を積み、高級多店舗ブランドやホテルグループの事業本部長へ。', type_moments = '{"複数店舗の数字を並べて比較するのが日課になっている","品質のブレを見つけると原因を突き止めたくなる","出店計画を見ると、次の展開先が気になる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T18'), compatible_reason = 'T18の緻密な収益分析は、COOとしての意思決定の裏付けになる。数字に強い右腕として事業運営を支えてくれる。' where type_code = 'T22';
update diagnosis_types set personality_analysis = '自分の美学や価値観を、選ばれるブランドという形にしたいと考える起業家気質。強い世界観と、顧客の求めるものを見抜く目を併せ持つ。', ability_analysis = '独立心と審美眼、顧客設計力に優れ、直感を頼りに新しい店を立ち上げる。挑戦志向が高いオーナー適性がある。', growth_advice = '初期投資の大きさや、自分の感性への依存度の高さがリスクになりやすい。信頼できる相談相手を持ち、感性と客観的な判断のバランスを取りたい。', career_path = '高級店オーナーやブランド創業者として、自分の世界観を体現する店を持つキャリアが向く。オーナーシェフとしての道も。', type_moments = '{"『こんな店があったら通いたい』を実際に作ってしまう","内装や器、一つひとつに妥協できない","自分の美学に共感してくれるお客様がいると心から嬉しい"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T19'), compatible_reason = 'T19のブランド設計力は、自分の美学を外に伝える発信力として機能する。世界観を広める最良のパートナーになる。' where type_code = 'T23';
update diagnosis_types set personality_analysis = '食への憧れを、一つの店にとどめず企業としての価値にまで育てたいと考える経営者気質。資本・人材・海外展開まで見据えた大きな視座を持つ。', ability_analysis = '経営力とブランド群管理、長期的な成長戦略に強みがあり、データに基づいて大きな意思決定を行う。組織全体を動かす役割に向く。', growth_advice = '拡大を優先しすぎて現場の解像度が下がることがある。定期的に一店舗一店舗の実情に触れる機会を意識的に持ちたい。', career_path = 'CEOや投資責任者、グループ経営として、複数の高級ブランドを統合的に育てる立場へ。将来的な代表取締役としての適性も高い。', type_moments = '{"一つの成功店を見ると、グループ展開の可能性を考える","海外の高級ブランド事例をつい研究してしまう","『このブランド群を10年後どうするか』を常に描いている"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T20'), compatible_reason = 'T20が描く緻密な成長戦略は、CEOとしての大きな意思決定を支える設計図になる。ビジョンと戦略が噛み合う組み合わせ。' where type_code = 'T24';
update diagnosis_types set personality_analysis = '大きな戦略より、現場で今日から実行できる小さな工夫を積み重ねることに手応えを感じるタイプ。商品配置や声かけなど、地に足のついた改善を好む。', ability_analysis = '改善力と実行力、売上感覚に優れ、直感的に『何を変えれば数字が動くか』を見抜く。専門性の高い現場改善職に向く。', growth_advice = '目の前の店舗だけを見て局所最適になったり、次々と施策を打って現場が疲弊することがある。改善の優先順位をつけ、一つずつ定着させる意識を持ちたい。', career_path = '店舗改善や販促、店長補佐として経験を積み、改善担当や副店長として複数店舗の底上げに関わっていく。', type_moments = '{"商品の陳列を少し変えただけで売上が動くと嬉しくなる","『なぜあの店は繁盛しているか』を観察せずにいられない","小さな改善の積み重ねが、いつの間にか大きな数字になっている"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T29'), compatible_reason = 'T29は同じ現場感覚を、繁忙時の即断力として発揮する存在。改善のアイデアを実際の修羅場で試す最高の相棒になる。' where type_code = 'T25';
update diagnosis_types set personality_analysis = '店の数字の中に隠れたムダと伸びしろを見つけることに知的な面白さを感じるタイプ。感覚ではなく、原価や人件費といった具体的なデータで判断する。', ability_analysis = '分析力と利益管理に強みがあり、データに基づいて計画的に改善案を組み立てる。専門性の高い管理職に向く。', growth_advice = '数字の正しさにこだわるあまり、現場の納得感を置き去りにしたり、短期的な数字だけを追いすぎることがある。データを現場の言葉に翻訳して伝える工夫を持ちたい。', career_path = '管理会計や店舗分析、SV支援として経験を積み、チェーンや多店舗展開する企業の分析担当、管理責任者へ。', type_moments = '{"商品別の利益率を見ると、つい頭の中で並べ替えてしまう","『このメニュー、実は儲かっていない』に気づくのが得意","数字が改善した瞬間、地味に一番のやりがいを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T30'), compatible_reason = 'T30が進める標準化・多店舗管理に、分析データという裏付けを提供できる関係。仕組みを数字で支える名コンビ。' where type_code = 'T26';
update diagnosis_types set personality_analysis = '次に伸びる業態やメニューの気配を、誰よりも早く察知することに長けたタイプ。トレンドと顧客ニーズへの感度が高く、思いついたらすぐ試したくなる。', ability_analysis = '市場感覚と企画力、スピードに優れ、直感的に新しい業態のアイデアを形にする。専門性の高い開発職に向く。', growth_advice = '流行を追いすぎたり、十分な検証をしないまま突き進んでしまうことがある。小さく試して数字で確かめるステップを意識的に挟みたい。', career_path = '業態開発や市場調査、新店企画として経験を積み、企画担当や開発責任者として新しい業態を生み出す立場へ。', type_moments = '{"話題の店を見つけると、すぐ食べに行って分析したくなる","『これ、次来る』という直感がよく当たる","新しいアイデアを思いつくと、いてもたってもいられない"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T31'), compatible_reason = 'T31は同じ挑戦志向を、全国展開という大きなスケールで実践する存在。見つけたヒットの種を大きく育てるパートナーになる。' where type_code = 'T27';
update diagnosis_types set personality_analysis = 'テクノロジーの力で店舗経営をより軽く、強くすることに情熱を注ぐタイプ。データやツールを使って、感覚だけに頼らない経営を実現しようとする。', ability_analysis = 'DX推進力と戦略性、分析力に優れ、データに基づいて挑戦的な仕組みを作る。専門性の高い企画職に向く。', growth_advice = 'ツール導入が目的化したり、現場の実情に合わない仕組みを作ってしまうことがある。導入前に現場スタッフの声を丁寧に聞く姿勢を持ちたい。', career_path = 'DX企画やプロダクト企画として経験を積み、チェーンやデリバリー事業のDX責任者、企画責任者へ。', type_moments = '{"新しいPOSシステムやモバイルオーダーの話を聞くとワクワクする","『このデータ、もっと活用できるのでは』が口癖","手作業のオペレーションを見ると、自動化できないか考えてしまう"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T32'), compatible_reason = 'T32が描く多店舗展開の戦略に、テクノロジーという武器を提供できる関係。拡大のスピードと質を同時に高められる。' where type_code = 'T28';
update diagnosis_types set personality_analysis = 'ピークタイムの5分間にこそ、その店の本当の実力が出ると考えるタイプ。繁忙時ほど頭が冴え、全体を見渡して即座に判断を下せる。', ability_analysis = '即断力と統率力、危機対応力に優れ、直感的にその場の最適解を見つける。まとめる立場としての適性が高い。', growth_advice = '指示が多くなりすぎたり、忙しさの中で長期的な改善が後回しになることがある。落ち着いた時間に、繁忙時の対応を振り返って仕組み化する習慣を持ちたい。', career_path = '店長や時間帯責任者として現場を率い、繁盛店や大型店の店舗責任者として、より大きな規模の現場を任される。', type_moments = '{"満席の店内でも、誰が何をすべきか瞬時に見えている","『大丈夫、いける』と自分にもチームにも言い聞かせられる","修羅場を乗り越えた後の達成感が忘れられない"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T25'), compatible_reason = 'T25が積み重ねる現場改善は、繁忙時に自分が判断する材料そのもの。日々の工夫と瞬発力が噛み合う理想的な関係。' where type_code = 'T29';
update diagnosis_types set personality_analysis = '一店舗の成功をたまたまで終わらせず、百店舗で再現できる標準へ落とし込むことに使命感を持つタイプ。マニュアルや教育、数値管理を丁寧に整える。', ability_analysis = '標準化力と多店舗管理、教育力に優れ、データに基づいて仕組みを設計する。まとめる立場としての適性が高い。', growth_advice = '仕組みが硬直化したり、個店ごとの個性を失わせてしまうことがある。標準化すべき部分と、店舗の裁量に任せる部分を意識的に分けたい。', career_path = 'SVや運営統括、教育責任者として経験を積み、チェーン全体を見る統括部長へ。', type_moments = '{"優れた店舗の運営を見ると、すぐマニュアル化したくなる","新人教育の資料を見ると、つい改善したくなる","どの店舗でも同じ品質が出せていることに安心する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T26'), compatible_reason = 'T26の分析力は、標準化すべきポイントを数字で裏付けてくれる。仕組みづくりの精度をさらに高められる関係。' where type_code = 'T30';
update diagnosis_types set personality_analysis = '勝てる店の型を作り上げ、それをオーナーとともに全国へ広げていくことに情熱を燃やすタイプ。事業拡大への強い意欲と交渉力を持つ。', ability_analysis = '事業拡大力とオーナー支援、交渉力に優れ、直感的に成長のチャンスを見抜く。挑戦志向の高いリーダー適性がある。', growth_advice = '拡大を優先しすぎて、加盟店との摩擦が生まれることがある。オーナーの立場に立って、成長スピードと現場の負担のバランスを考えたい。', career_path = 'FC本部や加盟開発として経験を積み、FC業態全体を率いるFC責任者、事業責任者へ。', type_moments = '{"強い業態モデルを見ると『これは広げられる』とすぐ考える","オーナーとの交渉で、相手の本音を引き出すのが得意","出店数が増えるたびに手応えを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T27'), compatible_reason = 'T27が見つけるヒットの兆しを、全国規模の事業へ広げる役割を担える。種を見つける人と、育てて広げる人の好コンビ。' where type_code = 'T31';
update diagnosis_types set personality_analysis = '店舗数を増やしながらも、利益と品質を落とさないことにこだわる統合思考の持ち主。出店戦略、人材、資金、KPIを一つの絵として捉える。', ability_analysis = '拡大力と組織設計、収益管理に優れ、データに基づいて事業全体を成長させる。組織を動かすリーダーとしての適性が高い。', growth_advice = '成長速度を過信して現場を疲弊させてしまうことがある。拡大のスピードを、現場の育成ペースに合わせて調整する視点を持ちたい。', career_path = '事業部長やCOO、出店責任者として経験を積み、チェーンや複数ブランドを統括する事業本部長へ。', type_moments = '{"出店計画を立てるとき、人材と資金の両方を同時に考えている","店舗数が増えても、品質のブレがないか気になる","経営指標が全体としてどう動いているかを俯瞰するのが好き"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T28'), compatible_reason = 'T28が推進するDXの仕組みは、多店舗を軽く強く運営するための武器になる。拡大戦略とテクノロジーが噛み合う組み合わせ。' where type_code = 'T32';
update diagnosis_types set personality_analysis = '火加減という誰もが軽視しがちな一瞬に、料理の完成度がすべて宿ると信じているタイプ。素材と対話するように熱を入れ、言葉より手先の感覚で状況を判断する。難しい素材ほど燃える職人気質。', ability_analysis = '技術精度と集中力、鋭い感覚に優れ、直感的な判断でその場の最適な火入れを見極める。専門性を突き詰めるスペシャリストとしての適性が高い。', growth_advice = '感覚に頼りすぎて、他者への技術継承が難しくなることがある。『なぜその火加減にしたのか』を言葉にする練習をすると、後進育成の場でも力を発揮できる。', career_path = '焼き手や肉料理人として技術を磨き、鉄板焼や焼鳥、フレンチの現場で経験を積み、料理長候補として専門性を極めていく。', type_moments = '{"炭火や鉄板の音と色だけで、火加減の答えが分かる","同じ素材でも、その日の状態を見て焼き方を微調整する","『あと一秒』のズレが気になって仕方ない"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T37'), compatible_reason = 'T37は同じ技術への情熱を、育成と統率という形で厨房全体に広げる存在。磨いた腕を安心して発揮できる舞台を整えてくれる。' where type_code = 'T33';
update diagnosis_types set personality_analysis = '『おいしい』という感覚を、偶然ではなく理論として解き明かしたいと考えるタイプ。試作と計測を繰り返し、感覚を誰もが再現できる知識に変換することに知的な喜びを感じる。', ability_analysis = '研究力と分析力、改善への執着に優れ、データに基づいて味を組み立てる。専門性の高い開発・研究職に向く。', growth_advice = '完成度を追求しすぎて開発が長引いたり、顧客が本当に求めているものとずれてしまうことがある。試作の早い段階で現場やお客様の声を取り入れる仕組みを持ちたい。', career_path = 'R&Dや商品開発、品質管理として経験を積み、メーカーやラボ、高級店の開発責任者として、味の研究を事業の力に変えていく。', type_moments = '{"同じ料理を何十回も試作して、微差にこだわる","『なぜおいしいのか』を成分や工程で説明したくなる","味の再現性が取れた瞬間、達成感で満たされる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T38'), compatible_reason = 'T38が進める品質の標準化に、研究で裏付けたレシピと理論を提供できる関係。味の再現性を科学と仕組みの両面から支える。' where type_code = 'T34';
update diagnosis_types set personality_analysis = '既存の料理の枠に収まることを窮屈に感じ、自分だけの表現を追い求めるタイプ。常識や前例よりも、自分の感性が『次に来る』と告げるものを信じて突き進む。', ability_analysis = '独創性と表現力、挑戦心に優れ、直感的に新しい料理表現を生み出す。既存の枠を超えるクリエイターとしての適性が高い。', growth_advice = '独自性を追い求めるあまり独善的になったり、他者が再現できない属人的な料理になりやすい。信頼できるスタッフと工程を共有し、表現を仕組みに落とし込む努力も必要。', career_path = 'シェフやクリエイターとしてガストロノミーや創作料理の現場で腕を磨き、料理長やオーナーシェフとして自分の世界観を掲げる店を持つ道へ。', type_moments = '{"『こんな料理、見たことない』と言われると心が躍る","既存のレシピ通りに作ることに退屈さを感じる","一皿の盛り付けに、何時間でも向き合える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T39'), compatible_reason = 'T39は同じ挑戦心を、新しい土地でのブランド立ち上げという形で発揮する存在。独創的な表現を、新しい市場という舞台で試せる関係になる。' where type_code = 'T35';
update diagnosis_types set personality_analysis = '感性だけに頼らず、調理科学とデータを駆使して忘れられない食体験を設計しようとするタイプ。感覚と理論、両方の言語を使いこなす稀有な存在。', ability_analysis = '科学的思考と創造性、精密さを兼ね備え、データに基づいて挑戦的な料理体験を組み立てる。高度な開発職としての適性が高い。', growth_advice = '設備投資やコストの負担が大きくなったり、表現が難解になりすぎてお客様に伝わりにくくなることがある。技術の複雑さと、体験としての分かりやすさのバランスを意識したい。', career_path = '研究シェフや商品開発として経験を積み、ガストロノミーや高級ホテルの開発シェフ、R&D責任者として食体験の最前線を切り拓いていく。', type_moments = '{"調理科学の論文や技法書を読むのが純粋に楽しい","『この温度と圧力なら、こういう食感になる』が計算できる","感性で生まれたアイデアを、理論で裏付けたくなる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T40'), compatible_reason = 'T40が持つブランド構築力と経営視点は、科学的に磨いた料理体験を世に広める力になる。技術と事業をつなぐ理想的な関係。' where type_code = 'T36';
update diagnosis_types set personality_analysis = '自分の腕を極めるだけでなく、その技術と基準を厨房全体、そして次の世代へ伝えることに責任感を持つタイプ。技術者でありながら、育てる人でもある。', ability_analysis = '卓越した技術と育成力、統率力を兼ね備え、直感的な判断で厨房を導く。まとめる立場としての適性が高い。', growth_advice = '自分の高い基準をスタッフに求めすぎて、プレッシャーになることがある。また後継者育成には時間がかかるため、焦らず段階的に任せていく姿勢が大切。', career_path = '料理長として現場を率い、高級店やホテルでの経験を積んで、総料理長として複数の厨房と人材育成を統括する立場へ成長していく。', type_moments = '{"自分の技術より、育てたスタッフの成長に誇りを感じる","厨房に入った瞬間、乱れている箇所にすぐ気づく","後輩が独り立ちする瞬間が、何より感慨深い"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T33'), compatible_reason = 'T33が持つ卓越した感覚技術は、自分が育てたい厨房文化の核になる。教える相手としてもプレイヤーとしても信頼できる存在。' where type_code = 'T37';
update diagnosis_types set personality_analysis = '名店の味を、一つの厨房だけの奇跡で終わらせず、どの店舗でも再現できる仕組みに変えることに使命感を持つタイプ。感覚を工程とレシピに落とし込む翻訳者的な役割を担う。', ability_analysis = '品質管理と標準化、教育力に優れ、データに基づいて複数拠点の料理品質を統一する。組織を支えるまとめ役としての適性が高い。', growth_advice = '標準化を徹底しすぎて、現場の創造性を抑えてしまったり、現場スタッフの反発を招くことがある。ルールの理由を丁寧に伝え、現場の工夫を吸い上げる余地も残したい。', career_path = '品質統括やセントラルキッチン責任者として経験を積み、高級チェーンやホテルグループの統括料理長、品質責任者として味の一貫性を守る立場へ。', type_moments = '{"どの店舗で食べても同じ味かどうか、つい確認したくなる","レシピの工程を見ると、あいまいな表現を数値化したくなる","新人でも一定の品質が出せる仕組みができると安心する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T34'), compatible_reason = 'T34の研究力が生み出す再現性の高いレシピは、標準化の土台として最適。味の科学と品質管理が噛み合う関係。' where type_code = 'T38';
update diagnosis_types set personality_analysis = '見知らぬ土地であっても、自分の技術と感性を武器に新しい食の旗を立てられるタイプ。文化の違いを恐れるより、適応しながら挑戦することに燃える開拓者気質。', ability_analysis = '越境力と技術、適応力に優れ、直感的に新しい市場でブランドを立ち上げる力を持つ。挑戦志向の高いリーダー適性がある。', growth_advice = '現地の文化理解が不足したり、運営基盤が整わないまま突き進んでしまうことがある。技術だけでなく、現地の商習慣やパートナーとの信頼構築にも時間をかけたい。', career_path = '海外シェフや新店立ち上げの現場で経験を積み、立ち上げ料理長やブランドシェフとして、新しい市場に自分の看板を打ち立てていく。', type_moments = '{"海外の見知らぬ食材を見ると、まず試してみたくなる","『前例がない市場』と聞くとむしろやる気が出る","現地の食文化と自分の技術を掛け合わせるのが楽しい"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T35'), compatible_reason = 'T35が持つ独創的な表現力は、新しい市場でブランドの個性を打ち出す武器になる。挑戦心が重なる最良のパートナー。' where type_code = 'T39';
update diagnosis_types set personality_analysis = '一皿の魅力を、料理そのものにとどめず、商品・空間・発信・複数店舗へと広げていく経営者気質のシェフ。料理人でありながら、事業家としての視座も持つ。', ability_analysis = 'ブランド構築力と経営視点、創造性を兼ね備え、データに基づいて料理を事業へと発展させる。組織を動かすリーダーとしての適性が高い。', growth_advice = '事業の広がりとともに現場に立つ時間が減り、個人ブランドへの依存が強まることがある。自分がいなくても料理と世界観が保たれる仕組みづくりを意識したい。', career_path = 'シェフプロデューサーやブランド監修として経験を積み、代表シェフ、プロデューサーとして複数業態・複数店舗を束ねる立場へ成長していく。', type_moments = '{"一皿のアイデアを見ると、すぐ商品化や店舗展開を考えてしまう","自分の料理がメディアやSNSでどう語られるか気になる","厨房よりも、ブランド全体の物語を描くことに燃える瞬間がある"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T36'), compatible_reason = 'T36が磨き上げる科学的で精緻な料理体験は、ブランドの核となる説得力を与えてくれる。技術力と事業展開力が噛み合う組み合わせ。' where type_code = 'T40';
update diagnosis_types set personality_analysis = '特別な日ではなく、毎日の食卓にこそ本当の勝負があると考えるタイプ。派手さより、今日も変わらぬ美味しさを出し続けることに職人としての誇りを持つ。', ability_analysis = 'スピードと安定した品質、体力に優れ、直感的な判断で高速回転の現場をさばく。専門性の高い調理現場のプレイヤーとして力を発揮する。', growth_advice = '自分の技術に頼りすぎて属人化しやすく、忙しさの中で改善に時間を割けないことがある。うまくいっている動きを言語化し、周囲に共有する時間を意識的に作りたい。', career_path = '中華料理人や大衆調理の現場で腕を磨き、町中華や食堂の調理リーダーとして、日常の味を支える中心的な存在へ成長していく。', type_moments = '{"中華鍋を振る音とタイミングだけで火加減を合わせられる","『いつもの味』が出せていることに一番の安心を感じる","行列ができても、リズムを崩さず淡々とさばき続ける"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T45'), compatible_reason = 'T45は同じ現場感覚を、ピークタイムの統率力として発揮する存在。安定した腕を最大限活かせる修羅場を一緒に乗り越えられる。' where type_code = 'T41';
update diagnosis_types set personality_analysis = '『速さ』と『品質』は本来トレードオフではないと信じ、工程そのものを設計し直すことに面白さを感じるタイプ。感覚ではなく分析で厨房のムダを見つける。', ability_analysis = '工程設計と分析力、再現性の高い仕組みづくりに優れ、データに基づいて大量調理の品質を安定させる。専門性の高い管理職に向く。', growth_advice = '最適化を突き詰めすぎて、現場スタッフの創意工夫の余地を奪ってしまうことがある。仕組みを固めすぎず、現場からの改善提案を取り入れる余白を残したい。', career_path = '生産管理やオペレーション開発として経験を積み、給食やセントラルキッチン、チェーンの工程責任者、生産管理責任者へ成長していく。', type_moments = '{"厨房の動線を見ると、つい頭の中で配置換えを始めてしまう","『この工程、一手減らせるのでは』が口癖","大量調理でも品質のブレがないことに達成感を覚える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T46'), compatible_reason = 'T46が統率する大量調理の現場に、精緻な工程設計というエンジンを提供できる関係。仕組みと統率力が噛み合う理想的な組み合わせ。' where type_code = 'T42';
update diagnosis_types set personality_analysis = '限られた設備や予算をハンデと捉えず、アイデアと勢いで乗り越えることに燃えるタイプ。小さな場所からでも大きな話題を生み出せると信じている。', ability_analysis = '発想力と行動力、現場対応力に優れ、直感的にその場で売れる商品を生み出す。挑戦志向の高いスペシャリストとしての適性がある。', growth_advice = '勢いで進める分、運営の安定性や衛生管理が後回しになることがある。アイデアを実現する前に、最低限の仕組みと基準を整えておくと長く続けられる。', career_path = '屋台やキッチンカー、ポップアップの現場で経験を積み、商品開発やストリートフードの独立オーナーとして自分のアイデアを形にしていく。', type_moments = '{"『これ、屋台で出したら絶対売れる』が頭に浮かぶとすぐ試したくなる","限られた設備の中でどう工夫するかを考えるのが楽しい","行列ができた瞬間、疲れも吹き飛ぶ"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T47'), compatible_reason = 'T47は同じ現場発想を、ブランド創業という大きな挑戦で実践する存在。生まれたアイデアを一緒に育て、広げていけるパートナーになる。' where type_code = 'T43';
update diagnosis_types set personality_analysis = '『みんなが好きな味』を、勘ではなくデータで設計することに知的な面白さを感じるタイプ。嗜好調査や原価計算を駆使し、ヒットする商品を組み立てる。', ability_analysis = '商品企画力と市場理解、収益性への感度に優れ、データに基づいて大衆向けのヒット商品を生み出す。専門性の高い企画職に向く。', growth_advice = '万人受けを狙いすぎて商品が無難になったり、コストを優先して品質を妥協してしまうことがある。数字の裏にある『誰の、どんな瞬間の満足か』を忘れずにいたい。', career_path = '商品開発やメーカー企画として経験を積み、チェーンや食品メーカーの商品開発責任者として、日常に定着する商品を生み出していく。', type_moments = '{"新商品のヒット率をつい過去のデータと照らし合わせてしまう","『これは万人受けする』という直感がよく当たる","原価と満足度のギリギリのラインを攻めるのが得意"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T48'), compatible_reason = 'T48が築く強い生産システムは、企画した商品を安定して大量供給する力になる。企画と生産が噛み合う、事業として強い組み合わせ。' where type_code = 'T44';
update diagnosis_types set personality_analysis = '一番忙しい時間こそ、自分が最も頼られる瞬間だと感じるタイプ。大量の注文が飛び交う中でも優先順位を即座に判断し、現場を止めずに回し続ける。', ability_analysis = '瞬発力と判断力、体力に優れ、直感的にその場の最適な動きを見つける。忙しい環境で真価を発揮するリーダー適性がある。', growth_advice = '平常時の改善が後回しになったり、走り続けることで燃え尽きてしまうことがある。落ち着いた時間に、繁忙時の動きを振り返り仕組み化する習慣を持ちたい。', career_path = '厨房リーダーや時間帯責任者として経験を積み、繁盛する大衆店や居酒屋の調理責任者、店長候補として現場を率いていく。', type_moments = '{"注文が殺到するほど、逆に頭が冴えてくる","『誰が何を作っているか』が常に頭の中で見えている","ピークを乗り切った後の一体感が何よりの報酬"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T41'), compatible_reason = 'T41が積み上げる日々の安定した腕は、自分が繁忙時に頼る現場力そのもの。修羅場を共に乗り越える信頼できる相棒になる。' where type_code = 'T45';
update diagnosis_types set personality_analysis = '一皿の味だけでなく、千食分の安全とおいしさを同時に守ることに責任感を持つタイプ。人員配置、工程、衛生管理まで含めて『現場を統括する』ことに使命感を感じる。', ability_analysis = '統率力と衛生管理、標準化の力に優れ、データに基づいて大量調理を安定運営する。まとめる立場としての適性が高い。', growth_advice = '管理項目が多くなるほど柔軟性が失われたり、管理負荷で自分自身が疲弊することがある。権限を適切に委譲し、現場のメンバーに判断を任せる場面を意識的に増やしたい。', career_path = '工場や給食施設、セントラルキッチンの現場で経験を積み、工場長や給食責任者、CK責任者として大規模な調理オペレーションを統括していく。', type_moments = '{"何百食分の調理でも、衛生基準が守られているか常に気になる","現場の人員配置を見ると、ボトルネックにすぐ気づく","大きなトラブルなく一日を終えられた時に安堵する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T42'), compatible_reason = 'T42が設計する精緻な工程は、大量調理を統括する上での強力な武器になる。分析に基づく仕組みと現場統率が噛み合う関係。' where type_code = 'T46';
update diagnosis_types set personality_analysis = '特別な非日常ではなく、日常の親しみやすい味にこそブランドの可能性を見出すタイプ。現場で鍛えた商品力と独立心を武器に、自分の看板を掲げたいと考える。', ability_analysis = '商品力と独立心、現場感覚に優れ、直感的に売れる商品と店の形を作り上げる。挑戦志向の高いオーナー適性がある。', growth_advice = '店舗を拡大する過程で品質が落ちたり、自分にしかできないやり方に依存してしまうことがある。早い段階からレシピと工程を仕組み化し、誰でも再現できる形に整えたい。', career_path = '創業者やFCオーナーとして、ラーメンや中華、定食といった日常業態でブランドを立ち上げ、ブランド代表として全国展開を目指すキャリアが向く。', type_moments = '{"『この味を全国に広げたい』という思いが常にある","自分の商品にお客様が並んでくれると心から嬉しい","現場に立ちながらも、次の出店先を頭の中で考えている"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T43'), compatible_reason = 'T43が持つ発想力と現場対応力は、新しい商品やメニューの種を生み出す源になる。生まれたアイデアをブランドとして育てる好コンビ。' where type_code = 'T47';
update diagnosis_types set personality_analysis = '料理を一皿単位ではなく、強い生産システムとして捉える経営者気質のタイプ。製造、物流、品質、コストをすべて統合的に管理し、大規模な供給を実現しようとする。', ability_analysis = '生産管理と収益管理、組織力に優れ、データに基づいて事業全体を俯瞰した意思決定を行う。組織を動かすリーダーとしての適性が高い。', growth_advice = '効率とコストを追求しすぎて、現場の創造性が失われたり、品質とコストの間で葛藤が生じることがある。数字の最適化だけでなく、現場が誇りを持てる仕組みも大切にしたい。', career_path = '工場長や製造責任者、SCMとして経験を積み、食品工場やセントラルキッチンの事業責任者、製造本部長として大規模な供給体制を率いていく。', type_moments = '{"生産ラインの数字を見ると、コストと品質のバランスを瞬時に計算する","『このシステムなら何十万食でも対応できる』を考えるのが好き","物流や在庫の最適化にひそかにやりがいを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T44'), compatible_reason = 'T44が企画するヒット商品は、自分が築く生産システムに乗せることで真価を発揮する。企画と生産基盤が両輪となる強い組み合わせ。' where type_code = 'T48';
update diagnosis_types set personality_analysis = '優れた素材や職人技の裏にある物語を見抜き、それを『選ばれる商品』として編集することに喜びを感じるタイプ。単なる目利きにとどまらず、価値を伝える企画力を併せ持つ。', ability_analysis = '目利きと企画力、物語化のセンスに優れ、直感的に商品の魅力を編み上げる。専門性の高い商品開発職としての適性が高い。', growth_advice = 'こだわりが強くなるほど原価が上がったり、市場が狭くなりやすい。届けたい価値を保ちながら、より多くの人に届く価格設計やチャネルも視野に入れたい。', career_path = '商品プロデューサーやバイヤーとして経験を積み、高級惣菜や菓子、ギフトの商品責任者として、素材の価値を商品に変える力を磨いていく。', type_moments = '{"優れた素材に出会うと、その背景にある物語を掘り下げたくなる","『これは高くても納得できる』を言葉と体験で説明できる","パッケージや説明文の一文にまでこだわってしまう"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T53'), compatible_reason = 'T53は同じ審美眼を、複数商品を束ねるブランド統括という立場で発揮する存在。編み上げた商品の物語を、より大きな舞台で輝かせてくれる。' where type_code = 'T49';
update diagnosis_types set personality_analysis = '高い品質と利益、どちらも譲らずに両立させることに使命感を持つタイプ。高価な素材や複雑な工程を、感覚ではなく数字で分解して最適点を見つけ出す。', ability_analysis = '原価管理と価格設計、分析力に優れ、データに基づいて価値と採算のバランスを設計する。専門性の高い管理職に向く。', growth_advice = '数字を重視しすぎて、現場が大切にしている感性や作り手のこだわりを軽視してしまうことがある。数字の裏にある職人の想いにも耳を傾ける姿勢を持ちたい。', career_path = '原価管理や商品収益管理として経験を積み、高級食品やホテルの収益担当、管理責任者として、価値と利益の両立を支える立場へ。', type_moments = '{"高級素材を見ると、まず原価と粗利を計算してしまう","『この価格でも十分に価値が伝わる』を数字で立証したくなる","複雑な工程の中に、コスト削減の余地を見つけると嬉しい"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T54'), compatible_reason = 'T54が率いる事業運営に、精緻な原価と価格の設計という裏付けを提供できる関係。数字に強い右腕として事業を支える。' where type_code = 'T50';
update diagnosis_types set personality_analysis = '商品を単なるモノではなく、『持ちたくなる物語』として仕立てることに情熱を注ぐタイプ。ネーミングやデザイン、世界観づくりへの感度が高い。', ability_analysis = '世界観構築力と企画力、発信力に優れ、直感的に新しいブランドの姿を描く。挑戦志向の高いクリエイターとしての適性がある。', growth_advice = '見た目や物語づくりを優先しすぎて、現場の製造実態やコストとの間にギャップが生まれることがある。ブランドを支える現場との対話を大切にしたい。', career_path = 'ブランド企画やクリエイティブ職として経験を積み、菓子や酒、高級食品のブランドマネージャーとして、世界観を商品に宿す力を磨いていく。', type_moments = '{"商品を見ると、まずそのネーミングやパッケージのストーリーを考える","『このブランド、持っていたい』と思わせる仕掛けを考えるのが好き","世界観が伝わった瞬間の反応にやりがいを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T55'), compatible_reason = 'T55は同じ美意識を、自分のブランドとして体現する存在。描いた世界観を、実際のブランド創業という形で一緒に実現できる。' where type_code = 'T51';
update diagnosis_types set personality_analysis = '高い価値を持つ商品を、より広い市場に届けるための新しい道を切り拓くことに関心を持つタイプ。データと顧客理解を武器に、新しいチャネルや事業モデルを設計する。', ability_analysis = '事業開発力と市場分析、収益設計に優れ、データに基づいて挑戦的な新規事業を組み立てる。専門性の高い事業開発職に向く。', growth_advice = '分析に時間をかけすぎたり、拡大を急ぐあまりブランドの価値を損なってしまうことがある。数字の検証と同時に、ブランドの世界観を守る視点も持ち続けたい。', career_path = '事業開発やアライアンス担当として経験を積み、EC・百貨店・海外展開など新しいチャネルの事業開発責任者として活躍していく。', type_moments = '{"高級ブランドの新しい販路を見ると、その戦略を分析したくなる","『この商品、海外でも通用するのでは』とすぐ考える","市場データと顧客インサイトをすり合わせるのが得意"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T56'), compatible_reason = 'T56が描くグローバルな経営ビジョンを、具体的な事業開発として実現する役割を担える。戦略と実行をつなぐ心強い関係。' where type_code = 'T52';
update diagnosis_types set personality_analysis = '複数の商品や店舗をバラバラのままにせず、一つの『憧れ』としてまとめ上げることに使命感を持つタイプ。審美眼と統率力を併せ持ち、ブランド全体を編集する。', ability_analysis = '統合力と審美眼、統率力に優れ、直感的な判断でブランド全体の価値を高める。まとめる立場としての適性が高い。', growth_advice = '統括する範囲が広がるほど現場への負荷が増したり、個別商品の個性が薄れてしまうことがある。全体最適と個別商品の魅力、両方に目を配る意識を持ちたい。', career_path = 'ブランド統括やクリエイティブ責任者として経験を積み、高級食品や複数ブランドを束ねるブランドディレクターとして活躍していく。', type_moments = '{"複数の商品ラインを見ると、統一感のなさが気になってしまう","『このブランド全体で何を伝えたいか』を常に意識している","バラバラな取り組みが一つの世界観にまとまる瞬間に興奮する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T49'), compatible_reason = 'T49が持つ目利きと物語化の力は、ブランド全体を彩る個々の商品の核になる。統括する上で欠かせない信頼できる存在。' where type_code = 'T53';
update diagnosis_types set personality_analysis = '高付加価値な商品を、一過性で終わらせず強い供給体制へと育てることに情熱を注ぐタイプ。品質、製造、販売、組織まで含めて事業として俯瞰する。', ability_analysis = '事業運営力と品質管理、収益力に優れ、データに基づいてプレミアム事業を安定的に成長させる。組織を率いるリーダーとしての適性が高い。', growth_advice = '管理項目が増えすぎたり、成長の過程でブランドが硬直化してしまうことがある。効率化を進めながらも、ブランドが本来持つ情熱や物語を失わない工夫を持ちたい。', career_path = 'COOや事業部長として経験を積み、高級食品やD2Cブランドの事業本部長として、プレミアム事業全体の成長を牽引していく。', type_moments = '{"品質・製造・販売のバランスを常に俯瞰して見ている","事業の数字が安定して伸びると、地道な積み重ねに満足感を覚える","組織が大きくなっても、ブランドの核がぶれていないか気にする"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T50'), compatible_reason = 'T50が設計する精緻な原価と価格戦略は、事業を安定成長させるための重要な武器になる。数字に強い右腕として頼れる関係。' where type_code = 'T54';
update diagnosis_types set personality_analysis = '最高の素材と自分の美学を掛け合わせ、新しいブランドを世に送り出したいと考える起業家気質のタイプ。独立心と強い審美眼を武器に、自分の手でゼロから作り上げる。', ability_analysis = '独立心と目利き、ブランド構築力に優れ、直感的に新しい高級ブランドの形を描く。挑戦志向の高いオーナー適性がある。', growth_advice = '初期投資の負担が大きくなったり、狙う市場が小さくなりやすい。自分の美学を貫きながらも、事業として持続可能な規模と価格設計を意識したい。', career_path = '創業者やブランドオーナーとして、酒・菓子・調味料といった領域で自分だけの高級ブランドを立ち上げ、CEOとして育てていくキャリアが向く。', type_moments = '{"『こんなブランドがあったら手に取りたい』を実際に作ってしまう","素材選びから最後の一手まで、妥協せず向き合える","自分の美学に共感してくれる顧客との出会いに深い喜びを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T51'), compatible_reason = 'T51が持つ世界観構築力と発信力は、自分の美学を広く伝えるための強力な武器になる。ブランドを育てる最良のパートナー。' where type_code = 'T55';
update diagnosis_types set personality_analysis = '食への憧れを、一つのブランドにとどめず世界で愛される企業へと育てたいと考える経営者気質のタイプ。ブランドポートフォリオ、資本、海外展開まで見据えた大きな視座を持つ。', ability_analysis = '経営力と海外戦略、ブランド群管理に優れ、データに基づいて高付加価値事業をグローバルに展開する。組織全体を動かす役割に向く。', growth_advice = '拡大を進めるほどブランドの個性が希薄化したり、現場との距離が開いてしまうことがある。定期的に現場やブランドの原点に立ち返る機会を意識的に持ちたい。', career_path = 'CEOやグループ経営として、複数の高級食品ブランドを統合的に育て、海外市場も含めた事業を率いる代表取締役としてのキャリアが向く。', type_moments = '{"一つの成功ブランドを見ると、グローバル展開の可能性を考える","海外の高級ブランド事例を研究するのが習慣になっている","『このブランド群を10年後どう育てるか』を常に描いている"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T52'), compatible_reason = 'T52が切り拓く新しい事業開発とチャネルは、グローバル経営ビジョンを実現する具体的な足がかりになる。戦略と実行が噛み合う組み合わせ。' where type_code = 'T56';
update diagnosis_types set personality_analysis = '『おいしい』と『売れる』は必ずしも一致しないと知りながら、その交差点を瞬時に見抜くことに長けたタイプ。感覚と市場理解の両方を武器に、ヒットの種を素早く判断する。', ability_analysis = '目利きと市場感覚、判断力に優れ、直感的にヒットする商品を見極める。専門性の高いバイヤー・MD職としての適性が高い。', growth_advice = '勘に頼りすぎて根拠を説明しづらかったり、目先のヒットを追って長期的なブランド価値を軽視してしまうことがある。判断の理由を言語化する習慣を持つと、周囲の信頼をより得やすくなる。', career_path = 'バイヤーや商品選定、MDとして経験を積み、小売や中食、ECの商品担当として、市場の『次の売れ筋』を見抜く力を磨いていく。', type_moments = '{"新商品を一口食べただけで『これは売れる』と分かる","売場を歩くと、つい競合商品の売れ行きを観察してしまう","自分の見立てが数字で証明された瞬間、密かにガッツポーズ"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T61'), compatible_reason = 'T61は同じ商品感覚を、開発から発売までを推進する立場で発揮する存在。見抜いたヒットの種を、実際の商品として形にしてくれる。' where type_code = 'T57';
update diagnosis_types set personality_analysis = '人々の『好き』という感覚を、購買データや口コミといった事実の中から読み解こうとするタイプ。感覚に頼らず、仮説と検証を繰り返して確からしさを積み上げる。', ability_analysis = '分析力と仮説検証力、洞察力に優れ、データに基づいて商品や市場の可能性を発見する。専門性の高いリサーチ職に向く。', growth_advice = 'データに没頭するあまり現場の温度感を見失ったり、数字に表れない微妙な感覚を軽視してしまうことがある。現場に足を運び、データの裏にある人の声を確かめる時間を持ちたい。', career_path = 'データ分析やリサーチとして経験を積み、フードテック企業やメーカーのアナリスト、研究担当として市場の可能性を発掘していく。', type_moments = '{"購買データや口コミを見ると、隠れたパターンを探したくなる","『なぜこの商品が伸びているのか』を仮説立てて検証したくなる","データが自分の直感と一致した瞬間に手応えを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T62'), compatible_reason = 'T62が統括する食品事業の意思決定に、精緻なデータ分析という裏付けを提供できる関係。数字に強い頭脳として事業運営を支える。' where type_code = 'T58';
update diagnosis_types set personality_analysis = '『定番』という言葉に安住せず、その中に次のヒットを仕込むことに喜びを感じるタイプ。既存の組み合わせや提供方法の常識を疑い、素早く新しい形を試す。', ability_analysis = '企画力と発想力、スピードに優れ、直感的に新しいメニューの形を生み出す。専門性の高い開発職としての適性が高い。', growth_advice = '奇抜さを優先しすぎたり、原価や運営のしやすさを軽視してしまうことがある。アイデアを形にする前に、現場で無理なく再現できるかを確認する視点を持ちたい。', career_path = 'メニュー開発やクリエイターとして経験を積み、チェーンや中食、デリバリーの商品企画、開発担当として新しい定番を生み出していく。', type_moments = '{"定番メニューを見ると『これ、もっと面白くできる』と考えてしまう","異なる料理のジャンルを掛け合わせるアイデアが次々浮かぶ","試作したメニューが話題になった瞬間が一番の快感"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T63'), compatible_reason = 'T63は同じ挑戦心を、飲食スタートアップの創業という大きな挑戦で実践する存在。生まれたアイデアを、新しい事業として一緒に育てられる。' where type_code = 'T59';
update diagnosis_types set personality_analysis = '飲食現場の『不便』や『非効率』を放っておけないタイプ。テクノロジーとデータの力で、感覚的に語られがちな課題を解決可能なプロダクトへと落とし込む。', ability_analysis = '課題発見力と技術理解、事業性への感度に優れ、データに基づいて挑戦的なサービスを設計する。専門性の高いプロダクト開発職に向く。', growth_advice = '技術や開発を優先しすぎて、現場の実情に合わないプロダクトになってしまうことがある。開発の早い段階から現場スタッフの声を取り入れる仕組みを持ちたい。', career_path = 'PdMやフードテック企画、DX担当として経験を積み、SaaSやデリバリー、ロボティクス領域のPdM、事業開発として飲食の課題を解決していく。', type_moments = '{"現場のムダな作業を見ると『自動化できないか』とすぐ考える","新しいPOSやロボット導入の話を聞くとワクワクする","自分が作ったプロダクトで現場が楽になった瞬間に達成感を覚える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T64'), compatible_reason = 'T64が描く食産業全体の変革ビジョンに、具体的なプロダクトという実行力を提供できる関係。構想と実装がかみ合う強力な組み合わせ。' where type_code = 'T60';
update diagnosis_types set personality_analysis = '一つのアイデアを、実際に売場に並ぶ商品として完成させることに手応えを感じるタイプ。企画、試作、製造、販売という多くの工程をまとめ上げる調整力を持つ。', ability_analysis = '推進力と調整力、商品理解に優れ、直感的に関係者を巻き込みながらプロジェクトを前に進める。まとめる立場としての適性が高い。', growth_advice = '各部門との調整に追われすぎたり、関係者の要望を取り入れるうちに商品が妥協の産物になってしまうことがある。譲れない軸を最初に明確にしておくと、ぶれずに進められる。', career_path = '商品開発リーダーやPMとして経験を積み、メーカーやチェーンの開発責任者、PMとして商品を発売まで導く役割を担っていく。', type_moments = '{"企画会議から発売まで、全工程を頭の中で描きながら動いている","関係部署の意見がまとまらない時、つい調整役を買って出る","自分が関わった商品が売場に並ぶ瞬間が一番の達成感"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T57'), compatible_reason = 'T57が持つ鋭い目利きと市場感覚は、開発する商品の方向性を決める重要な羅針盤になる。見立てと実行力が噛み合う理想的な関係。' where type_code = 'T61';
update diagnosis_types set personality_analysis = '商品開発から製造、物流、営業まで、事業全体を一つの流れとして統括することに使命感を持つタイプ。部分最適ではなく、事業全体の成長を見据えて判断する。', ability_analysis = '事業運営力と統率力、収益管理に優れ、データに基づいて食品事業全体を成長させる。組織を率いるリーダーとしての適性が高い。', growth_advice = '部門間の調整に多くの時間を取られたり、現場との距離が開いてしまうことがある。定期的に現場に足を運び、数字だけでなく一次情報に触れる機会を意識的に持ちたい。', career_path = '事業部長や本部長として経験を積み、食品メーカーや中食企業の事業部長、COOとして事業全体を牽引していく立場へ成長していく。', type_moments = '{"商品開発から営業まで、事業全体の数字を俯瞰して見ている","部門間の連携がうまくいくと、事業が一つにまとまった感覚を覚える","利益と成長、両方が伸びている瞬間に一番のやりがいを感じる"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T58'), compatible_reason = 'T58の緻密なデータ分析は、事業全体を統括する上での意思決定の裏付けになる。分析結果を実際の経営判断へ落とし込む名パートナー。' where type_code = 'T62';
update diagnosis_types set personality_analysis = '食にまつわる大きな課題を、大きな構想からではなく、小さく速い実験から解いていこうとするタイプ。現場の課題とテクノロジーを結びつけ、新しいサービスを生み出す行動力を持つ。', ability_analysis = '起業力と仮説検証力、行動力に優れ、直感的に新しい飲食サービスの形を作り上げる。挑戦志向の高いリーダー適性がある。', growth_advice = '資金繰りの厳しさや、事業運営の複雑さに直面しやすい。一人で抱え込まず、早い段階から信頼できる仲間や投資家との関係を築いておきたい。', career_path = '起業家や新規事業担当として経験を積み、フードテックやD2C、新業態の創業者、CEOとして自らの手で新しいサービスを生み出していく。', type_moments = '{"現場の課題を見ると『これはサービスにできる』とすぐ考える","小さく試して反応を見ることに、じっとしていられない性分","初期のユーザーが喜んでくれた瞬間が何より心を支える"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T59'), compatible_reason = 'T59が持つ発想力とスピード感は、新しいサービスや商品の核となるアイデアを生み出す源になる。挑戦心が重なる最良のパートナー。' where type_code = 'T63';
update diagnosis_types set personality_analysis = '食にまつわる『当たり前』そのものを疑い、テクノロジーと資本を使って産業構造ごと変えようとする、規格外のスケールで物事を考えるタイプ。', ability_analysis = '変革力と経営力、市場創造力に優れ、データに基づいて巨大な事業構想を描く。組織全体を動かす経営者としての適性が高い。', growth_advice = '構想が壮大になりすぎて実現可能性を見失ったり、現場の解像度が下がってしまうことがある。大きなビジョンを、着実に検証できる小さな一歩に分解する意識を持ちたい。', career_path = 'CEOや事業創造、投資責任者として、フードテックやプラットフォーム事業を通じて食産業全体の構造を変えていく経営者としてのキャリアが向く。', type_moments = '{"既存の食産業の仕組みを見ると『これは変えられる』と考えてしまう","テクノロジーと資本を組み合わせた事業構想を描くのが楽しい","小さな実験が巨大な市場変革の兆しに見える瞬間に興奮する"}', compatible_type_id = (select id from diagnosis_types where type_code = 'T60'), compatible_reason = 'T60が生み出す具体的なプロダクトは、壮大な変革構想を現実の形にする実行力になる。ビジョンと実装が噛み合う強力な組み合わせ。' where type_code = 'T64';
